BEGIN;
DO $guard$ BEGIN
 IF current_database() NOT LIKE 'mobile5_dms_task3_%' OR shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database') IS DISTINCT FROM 'Mobile5 DMS task3 isolated' THEN RAISE EXCEPTION 'Isolated Mobile DMS fixture required'; END IF;
 IF (SELECT count(*) FROM auth.users)<>0 THEN RAISE EXCEPTION 'Empty synthetic target required'; END IF;
END $guard$;
CREATE FUNCTION pg_temp.check_it(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label; END IF;RAISE NOTICE 'PASS %',label;END$$;
CREATE FUNCTION pg_temp.actor(n int) RETURNS void LANGUAGE sql AS $$SELECT set_config('request.jwt.claims',jsonb_build_object('sub','cccccccc-1111-4000-8000-'||lpad(n::text,12,'0'),'session_id','dddddddd-1111-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated')::text,true)::text$$;
