-- Fixture bridge mints a server ticket, restores the caller and consumes it with the authenticated role.
CREATE FUNCTION pg_temp.ticket(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE claims jsonb:=auth.jwt(); ticket uuid:=gen_random_uuid();
BEGIN
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM public.dms_question_authorize(ticket,(claims->>'sub')::uuid,(claims->>'session_id')::uuid,p);
 PERFORM set_config('request.jwt.claims',claims::text,true);
 RETURN p||jsonb_build_object('ticket',ticket);
END $$;
CREATE FUNCTION pg_temp.read_context(p jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$SELECT public.mobile_dms_question_context(pg_temp.ticket(p))$$;
CREATE FUNCTION pg_temp.reserve_inputs(doc bigint,refs jsonb,header jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER AS $$
DECLARE input uuid:=gen_random_uuid();BEGIN
 IF NOT public.dms_question_publish(jsonb_build_object('kind','reserve_input','documentId',doc,'inputId',input,'refs',refs,'header',header)) THEN RAISE EXCEPTION 'Writer input changed';END IF;
 RETURN jsonb_build_object('inputId',input);
END $$;
