SELECT pg_temp.check_it(NOT has_function_privilege('authenticated','public.dms_question_authorize(uuid,uuid,uuid,jsonb)','EXECUTE') AND NOT has_table_privilege('authenticated','erp_private.dms_question_tickets','SELECT') AND to_regprocedure('public.dms_question_writer_parent(bigint,jsonb,jsonb)') IS NULL,'ordinary clients cannot mint or read server tickets and no elevated provenance reader exists');
DO $$DECLARE p jsonb:=(SELECT v FROM m5 WHERE k='qdata');t jsonb;BEGIN
 BEGIN PERFORM public.mobile_dms_question_context(p);RAISE EXCEPTION 'unguarded read';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 t:=pg_temp.ticket(p);
 BEGIN PERFORM public.mobile_dms_question_context(t||'{"contextMode":"metadata_only"}');RAISE EXCEPTION 'ticket selection substituted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM pg_temp.actor(2);
 BEGIN PERFORM public.mobile_dms_question_context(t);RAISE EXCEPTION 'ticket principal substituted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM pg_temp.actor(1);
 PERFORM set_config('request.jwt.claims',(auth.jwt()||jsonb_build_object('session_id',gen_random_uuid()))::text,true);
 BEGIN PERFORM public.mobile_dms_question_context(t);RAISE EXCEPTION 'ticket session substituted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM pg_temp.actor(1);PERFORM public.mobile_dms_question_context(t);
 BEGIN PERFORM public.mobile_dms_question_context(t);RAISE EXCEPTION 'ticket reused';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END$$;
